package com.terminaldetector.drmd;
import com.terminaldetector.drmd.client.cloud.AltitudeCloudPolicy;
import org.junit.jupiter.api.Test;
import java.io.*;
import java.util.Properties;
import static org.junit.jupiter.api.Assertions.*;

class AltitudeCloudPolicyTest {
    @Test void strictLessFarSkyPassesWithoutChangingOpaqueOrLequalOwnership(){double legacyFar=AltitudeCloudPolicy.originalDepth(2000,.05,256),opaque=AltitudeCloudPolicy.originalDepth(32,.05,256);float less=AltitudeCloudPolicy.farDepthCeiling(true),lequal=AltitudeCloudPolicy.farDepthCeiling(false);assertFalse(legacyFar<1);assertEquals(Math.nextDown(1.0f),less);assertTrue(Math.min(legacyFar,less)<1);assertFalse(Math.min(legacyFar,less)<opaque);double stored24=Math.rint((double)less*0xFFFFFF)/0xFFFFFF;assertTrue(stored24<1&&stored24>opaque);assertEquals(1.0f,lequal);assertEquals(legacyFar,Math.min(legacyFar,lequal));assertTrue(Math.min(legacyFar,lequal)<=1);assertEquals(opaque,Math.min(opaque,less));}
    @Test void focusReferenceRatherThanEyeOffsetPreserves384AndWorksWithChangedLocalUp(){var policy=new AltitudeCloudPolicy(true,384,512,4096);assertEquals(0,new AltitudeCloudPolicy.ViewAltitude(384,385.62).weight(policy));assertTrue(policy.weight(385.62)>0);assertEquals(0,new AltitudeCloudPolicy.ViewAltitude(384,380).weight(policy));assertEquals(1,new AltitudeCloudPolicy.ViewAltitude(512,509).weight(policy));assertFalse(new AltitudeCloudPolicy.ViewAltitude(Double.NaN,385.62).valid());}
    @Test void oldConfigGetsCloudDefaultsWithoutChangingNativeOrIndependentChoices(){var p=new Properties();p.setProperty("presentationProfile","HYBRID_NATIVE");p.setProperty("hybridRender","false");assertEquals(new AltitudeCloudPolicy(true,384,512,4096),AltitudeCloudPolicy.read(p));assertEquals("HYBRID_NATIVE",p.getProperty("presentationProfile"));assertEquals("false",p.getProperty("hybridRender"));assertEquals(2,p.size());}
    @Test void explicitDisabledAndCustomValuesSurviveActualPropertiesStorage()throws IOException{var wanted=new AltitudeCloudPolicy(false,600,900,8192);var p=new Properties();wanted.write(p);var bytes=new ByteArrayOutputStream();p.store(bytes,"");var loaded=new Properties();loaded.load(new ByteArrayInputStream(bytes.toByteArray()));assertEquals(wanted,AltitudeCloudPolicy.read(loaded));}
    @Test void malformedAndNonfiniteSettingsStayBoundedAndCannotAlterNear384(){var p=new Properties();p.setProperty("cloudAltitudeStart","-Infinity");p.setProperty("cloudAltitudeFull","NaN");p.setProperty("cloudRange","nonsense");assertEquals(new AltitudeCloudPolicy(true,384,512,4096),AltitudeCloudPolicy.read(p));var clipped=new AltitudeCloudPolicy(true,-100,0,Float.MAX_VALUE);assertEquals(0,clipped.weight(224));assertEquals(0,clipped.weight(384));assertEquals(16384,clipped.range());assertTrue(clipped.fullHeight()>clipped.startHeight());}
    @Test void altitudeAndRangeTransitionsAreContinuousMonotoneAndFinite(){var p=new AltitudeCloudPolicy(true,384,512,4096);float last=0;for(int y=0;y<=2300;y++){float w=p.weight(y);assertTrue(w>=last&&w>=0&&w<=1);last=w;}assertEquals(0,p.weight(384));assertEquals(1,p.weight(512));assertTrue(p.weight(384.001)<.000001);assertEquals(1,p.radialAlpha(2000));assertEquals(0,p.radialAlpha(4096));assertEquals(0,p.radialAlpha(Double.NaN));assertEquals(0,new AltitudeCloudPolicy(false,384,512,4096).weight(2200));}
    @Test void originalDepthKeepsNearOpaqueGeometryInFrontOfExtendedClouds(){double near=.05,far=256;assertTrue(AltitudeCloudPolicy.originalDepth(16,near,far)<AltitudeCloudPolicy.originalDepth(189,near,far));assertEquals(1,AltitudeCloudPolicy.originalDepth(2000,near,far));assertEquals(1,AltitudeCloudPolicy.originalDepth(256,near,far),1e-12);assertEquals(0,AltitudeCloudPolicy.originalDepth(near,near,far),1e-12);}
    @Test void sourcePlaneHitIsCorrectForOffRayInterpolantsAndRejectsDegeneratePlanes(){double root=Math.sqrt(2);assertEquals(2000*root,AltitudeCloudPolicy.planeRay(0,1,0,100,-2000,50,1/root,-1/root,0),1e-9);assertEquals(1968,AltitudeCloudPolicy.planeRay(0,10,0,400,-1968,77,0,-1,0));assertTrue(Double.isNaN(AltitudeCloudPolicy.planeRay(0,0,0,0,-1,0,0,-1,0)));assertTrue(Double.isNaN(AltitudeCloudPolicy.planeRay(0,1,0,0,-1,0,1,0,0)));assertTrue(Double.isNaN(AltitudeCloudPolicy.planeRay(0,1,0,0,1,0,0,-1,0)));}
    @Test void realFourKAndPs1TargetsFitButOverflowAndOversizedTargetsDoNotShrink(){assertTrue(AltitudeCloudPolicy.acceptsTarget(3840,2160,16384));assertTrue(AltitudeCloudPolicy.acceptsTarget(640,360,16384));assertFalse(AltitudeCloudPolicy.acceptsTarget(0,864,16384));assertFalse(AltitudeCloudPolicy.acceptsTarget(Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE));assertFalse(AltitudeCloudPolicy.acceptsTarget(4096,2160,16384));assertEquals(AltitudeCloudPolicy.MAX_TARGET_BYTES,AltitudeCloudPolicy.MAX_PIXELS*12L);}
}
